def native_args(kernel,predicate):
    rows=kernel.get('native_query') if type(kernel) is dict else None
    if type(rows) is not list:
        return []
    for row in rows:
        if type(row) is dict and row.get('predicate')==predicate and type(row.get('arguments')) is list:
            return list(row.get('arguments'))
    return []


def query_predicates(kernel):
    result=[]
    rows=kernel.get('native_query') if type(kernel) is dict else None
    if type(rows) is not list:
        return result
    for row in rows:
        name=row.get('predicate') if type(row) is dict else None
        if type(name) is str and name not in result:
            result.append(name)
    return result


def add_unique(rows,row):
    if row not in rows:
        rows.append(row)


def put(rows,predicate,arguments):
    add_unique(rows,{'predicate':predicate,'arguments':arguments})


def checked_witnesses(rows,public,require_facts):
    if type(rows) is not list or len(rows)==0:
        return None
    result=[]
    has_facts=False
    for row in rows:
        if type(row) is not dict:
            return None
        field=row.get('field'); quote=row.get('quote'); text=public.get(field)
        if field not in ('facts','question') or type(quote) is not str or not quote or type(text) is not str or quote not in text:
            return None
        if field=='facts':
            has_facts=True
        add_unique(result,{'field':field,'quote':quote})
    if require_facts and not has_facts:
        return None
    return result


def add_record_witnesses(target,record,public):
    rows=checked_witnesses(record.get('witnesses') if type(record) is dict else None,public,True)
    if rows is None:
        return False
    for row in rows:
        add_unique(target,row)
    return True


def add_view_witnesses(target,view,public):
    rows=checked_witnesses(view.get('witnesses') if type(view) is dict else None,public,False)
    if rows is None:
        return False
    for row in rows:
        add_unique(target,row)
    return True


