def apply(inputs,premises):
    kernel=inputs.get('kernel',{}); public=inputs.get('public_case',{}); observation=inputs.get('observation')
    needed=required_components(kernel)
    if len(needed)==0:
        return {'bindings':[],'unresolved':['no_declared_component_for_actual_native_query']}
    if type(observation) is not dict:
        return {'bindings':[],'unresolved':['joint_observation_required']}
    unresolved=set(); combinations=[{'facts':[],'negative_givens':[],'witnesses':[],'complete':True}]
    for component_id in needed:
        component=observation.get(component_id)
        views=component.get('views') if type(component) is dict else None
        if type(views) is not list or len(views)==0:
            unresolved.add(component_id+'_observation_required')
            combinations=[]
            break
        next_combinations=[]
        for base in combinations:
            for view in views:
                partial=lower_component(component_id,view,public,kernel,unresolved)
                if partial is None:
                    continue
                facts=list(base.get('facts')); negatives=list(base.get('negative_givens')); witnesses=list(base.get('witnesses'))
                for row in partial.get('facts'):
                    add_unique(facts,row)
                for row in partial.get('negative_givens'):
                    add_unique(negatives,row)
                for row in partial.get('witnesses'):
                    add_unique(witnesses,row)
                next_combinations.append({'facts':facts,'negative_givens':negatives,'witnesses':witnesses,'complete':base.get('complete') and partial.get('complete')})
        combinations=next_combinations
    bindings=[]
    for combined in combinations:
        status='complete' if combined.get('complete') else 'unread'
        bindings.append({'inputs':{'facts':combined.get('facts'),'negative_givens':combined.get('negative_givens'),'extraction_status':status},'witnesses':combined.get('witnesses')})
    if len(bindings)==0:
        unresolved.add('no_coherent_joint_binding')
    return {'bindings':bindings,'unresolved':sorted(unresolved)}

